        &self.data
    }
}

verus! {

impl<V, Own> AtomicDataWithOwner<V, Own> {
    #[inline]
    pub fn new(data: V, permission: Tracked<Own>) -> Self {
        Self { data, permission }
    }
}

impl<V, Own> !Copy for AtomicDataWithOwner<V, Own> {

}

